  useEffect(()=>{refresh();try{setDark(localStorage.getItem("kas-osis-theme")==="dark");}catch{};},[]);
  useEffect(()=>{document.documentElement.dataset.theme=dark?"dark":"light";try{localStorage.setItem("kas-osis-theme",dark?"dark":"light");}catch{};},[dark]);
